INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-11-26-uk-budget-2025-mandate-confirmed', '2025-11-26', '2025-11', 'The UK''s Autumn Budget 2025 has confirmed that all VAT invoices in B2B and B2G transactions must be issued electronically from 1 April 2029, following a public consultation earlier in the year — with real-time reporting to HMRC deliberately excluded, at least initially.', '<h3>🇬🇧 Autumn Budget 2025 confirms UK e-invoicing mandate from April 2029</h3>
<p>Following a 12-week public consultation run jointly by HMRC and the Department for Business and Trade earlier in the year, the UK''s Autumn Budget 2025 has confirmed a genuine mandate: all VAT invoices between VAT-registered businesses (B2B), and between businesses and government bodies (B2G), must be issued electronically from 1 April 2029. Business-to-consumer transactions remain explicitly out of scope. This is a significant step for a market that, outside NHS procurement, has never required electronic invoicing at all — PDF invoices sent by email currently count as "electronic" under existing VAT guidance, and that''s set to change materially.</p>
<p>A deliberate design choice worth understanding clearly: real-time reporting to HMRC has been explicitly excluded from the initial 2029 requirements. This distinguishes the UK''s approach from clearance-model countries elsewhere in this tracker — the mandate is about structured invoice exchange between trading parties, not centralized government validation of every transaction as it happens. What actually counts as a compliant "e-invoice" going forward is also being tightened: standardised, machine-readable data flowing directly between financial systems, not merely a PDF attachment, however electronic that PDF might currently be considered.</p>
<p><strong>What this means for your team:</strong> April 2029 is genuinely distant compared to most deadlines in this tracker, but "no real-time reporting" doesn''t mean "nothing to plan for" — moving from PDF-based invoicing to genuinely structured, machine-readable exchange is a real systems change, not a policy footnote. If your current e-invoicing consists of emailing PDFs, that approach has a confirmed expiry date now, even if it''s still a few years off.</p>', 'https://www.gov.uk/government/consultations/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector/outcome/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector-consultation-response', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2025-11-26-uk-budget-2025-mandate-confirmed', id FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2025-11-26-uk-budget-2025-mandate-confirmed', 'en', 'Autumn Budget 2025 confirms UK e-invoicing mandate from April 2029', 'The UK''s Autumn Budget 2025 has confirmed that all VAT invoices in B2B and B2G transactions must be issued electronically from 1 April 2029, following a public consultation earlier in the year — with real-time reporting to HMRC deliberately excluded, at least initially.', '<h3>🇬🇧 Autumn Budget 2025 confirms UK e-invoicing mandate from April 2029</h3>
<p>Following a 12-week public consultation run jointly by HMRC and the Department for Business and Trade earlier in the year, the UK''s Autumn Budget 2025 has confirmed a genuine mandate: all VAT invoices between VAT-registered businesses (B2B), and between businesses and government bodies (B2G), must be issued electronically from 1 April 2029. Business-to-consumer transactions remain explicitly out of scope. This is a significant step for a market that, outside NHS procurement, has never required electronic invoicing at all — PDF invoices sent by email currently count as "electronic" under existing VAT guidance, and that''s set to change materially.</p>
<p>A deliberate design choice worth understanding clearly: real-time reporting to HMRC has been explicitly excluded from the initial 2029 requirements. This distinguishes the UK''s approach from clearance-model countries elsewhere in this tracker — the mandate is about structured invoice exchange between trading parties, not centralized government validation of every transaction as it happens. What actually counts as a compliant "e-invoice" going forward is also being tightened: standardised, machine-readable data flowing directly between financial systems, not merely a PDF attachment, however electronic that PDF might currently be considered.</p>
<p><strong>What this means for your team:</strong> April 2029 is genuinely distant compared to most deadlines in this tracker, but "no real-time reporting" doesn''t mean "nothing to plan for" — moving from PDF-based invoicing to genuinely structured, machine-readable exchange is a real systems change, not a policy footnote. If your current e-invoicing consists of emailing PDFs, that approach has a confirmed expiry date now, even if it''s still a few years off.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-23-uk-peppol-confirmed', '2026-06-23', '2026-06', 'As part of Tax Update 2026, HMRC has confirmed Peppol as the core interoperability network for the UK''s 2029 e-invoicing mandate, settling the single biggest open design question and confirming a decentralised model rather than centralised government clearance.', '<h3>🇬🇧 HMRC confirms Peppol as the UK''s e-invoicing network, settling the biggest open question</h3>
<p>As part of the "Tax Update 2026: Simplification, Modernisation and Fairness" package, HM Treasury and HMRC have officially confirmed that Peppol will be the core interoperability network underpinning the UK''s e-invoicing mandate ahead of its April 2029 start. This settles what had genuinely been the biggest open design question since the mandate was first confirmed at Autumn Budget 2025 — businesses and software vendors now have a clear technical direction to build toward, rather than working against multiple possible outcomes.</p>
<p>The announcement confirms a decentralised four-corner model: suppliers and buyers exchange structured invoices through Peppol access points, with no central government platform sitting in the middle and no real-time invoice data flowing to HMRC, at least in this initial phase. A UK-specific implementation — increasingly referred to as PINT UK — is being developed through a dedicated OpenPeppol UK Working Group, though it hasn''t been formally mandated as the required standard yet. This is a genuinely different posture from most clearance-model countries in this tracker: the UK is building interoperability infrastructure first, with digital reporting explicitly left as a possible later phase rather than a day-one requirement.</p>
<p><strong>What this means for your team:</strong> this is a deliberate signal from HMRC that businesses and software providers can start real implementation planning now, rather than waiting for the full roadmap due at Budget 2026. If your ERP or invoicing platform doesn''t yet have a credible path to Peppol connectivity, that''s worth raising with your vendor directly — "Peppol-ready" is likely to become a genuine procurement question well before 2029 arrives.</p>', 'https://www.gov.uk/government/consultations/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector/outcome/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector-consultation-response', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-23-uk-peppol-confirmed', id FROM countries WHERE name_en = 'United Kingdom';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-23-uk-peppol-confirmed', 'en', 'HMRC confirms Peppol as the UK''s e-invoicing network, settling the biggest open question', 'As part of Tax Update 2026, HMRC has confirmed Peppol as the core interoperability network for the UK''s 2029 e-invoicing mandate, settling the single biggest open design question and confirming a decentralised model rather than centralised government clearance.', '<h3>🇬🇧 HMRC confirms Peppol as the UK''s e-invoicing network, settling the biggest open question</h3>
<p>As part of the "Tax Update 2026: Simplification, Modernisation and Fairness" package, HM Treasury and HMRC have officially confirmed that Peppol will be the core interoperability network underpinning the UK''s e-invoicing mandate ahead of its April 2029 start. This settles what had genuinely been the biggest open design question since the mandate was first confirmed at Autumn Budget 2025 — businesses and software vendors now have a clear technical direction to build toward, rather than working against multiple possible outcomes.</p>
<p>The announcement confirms a decentralised four-corner model: suppliers and buyers exchange structured invoices through Peppol access points, with no central government platform sitting in the middle and no real-time invoice data flowing to HMRC, at least in this initial phase. A UK-specific implementation — increasingly referred to as PINT UK — is being developed through a dedicated OpenPeppol UK Working Group, though it hasn''t been formally mandated as the required standard yet. This is a genuinely different posture from most clearance-model countries in this tracker: the UK is building interoperability infrastructure first, with digital reporting explicitly left as a possible later phase rather than a day-one requirement.</p>
<p><strong>What this means for your team:</strong> this is a deliberate signal from HMRC that businesses and software providers can start real implementation planning now, rather than waiting for the full roadmap due at Budget 2026. If your ERP or invoicing platform doesn''t yet have a credible path to Peppol connectivity, that''s worth raising with your vendor directly — "Peppol-ready" is likely to become a genuine procurement question well before 2029 arrives.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-20-uk-open-questions-before-budget', '2026-07-20', '2026-07', 'With Peppol confirmed as the network but the full implementation roadmap not due until Budget 2026 in November, several genuinely open questions remain — including legacy EDI treatment, accreditation requirements, and whether a phased rollout will exempt smaller businesses initially.', '<h3>🇬🇧 What''s still undecided ahead of the UK''s Budget 2026 e-invoicing roadmap</h3>
<p>Confirming Peppol as the network answered one major question, but genuinely important design details remain open, with the full implementation roadmap not expected until Budget 2026 this November. Worth tracking rather than assuming settled: the specific UK Peppol data standards — mandatory fields, national requirements, and any UK-specific extensions — are still being drafted by a dedicated OpenPeppol UK Working Group, and requirements for becoming an accredited UK Peppol access point haven''t been published yet.</p>
<p>Two further open questions carry real practical weight. First, the treatment of legacy EDI systems: many UK businesses, particularly larger ones with established peer-to-peer EDI arrangements, don''t yet know how those existing setups will fit within the new framework, or whether they''ll need to be replaced entirely. Second, the rollout sequencing: industry commentary consistently expects a phased introduction — larger businesses first from April 2029, with smaller taxpayers potentially following from April 2030 — but this hasn''t been formally confirmed, and the exact thresholds remain unknown.</p>
<p><strong>What this means for your team:</strong> if your business relies on existing EDI arrangements with major trading partners, this is worth raising directly with them now rather than waiting for the roadmap to resolve it — a partner-by-partner conversation about transition plans is more useful at this stage than waiting on government guidance that isn''t ready yet. More broadly, treat "the mandate is 2029" as the confirmed part of the picture, and everything about exact scope, sequencing, and legacy-system treatment as still genuinely in motion until Budget 2026 actually lands.</p>', 'https://www.gov.uk/government/consultations/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector/outcome/promoting-electronic-invoicing-across-uk-businesses-and-the-public-sector-consultation-response', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-20-uk-open-questions-before-budget', id FROM countries WHERE name_en = 'United Kingdom';
